    if (scope2.bookCode === "BOOK-6") u.searchParams.set("view", "reconfiguration");
    const href = u.pathname + u.search + u.hash;
    await db2.prepare("INSERT INTO account_world_contexts(user_id,context_id,source_version,scope_json,source_json,href,created_at,expires_at) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(user_id,context_id,source_version) DO UPDATE SET source_version=excluded.source_version,source_json=excluded.source_json,href=excluded.href,expires_at=excluded.expires_at").bind(owner.userId, contextId, sourceVersion, JSON.stringify(scope2), JSON.stringify(metadata3), href, now, now + b.retentionDays * 864e5).run();
