function inspectBaziDiagramFidelity(diagrams) {
  return Object.entries(BAZI_DIAGRAM_FIDELITY_V1).map(([id2, spec]) => {
    const d = diagrams.find((d2) => d2.id === id2), errors = [];
    if (!d || d.visualGrammarId !== spec.grammar) errors.push("GRAMMAR");
    if (d) {
      const fixed = BAZI_DIAGRAM_FIDELITY_R1_ACCEPTED_CANDIDATE[id2];
      if (fixed) {
        const nodes = d.graph.nodes.map((n) => n.id), edges = d.graph.edges.map((e) => e.from + ">" + e.to);
        if (nodes.length !== fixed.nodes.length || fixed.nodes.some((n) => !nodes.includes(n))) errors.push("REQUIRED_NODE_TOPOLOGY");
        if (edges.length !== fixed.edges.length || fixed.edges.some((e) => !edges.includes(e))) errors.push("REQUIRED_EDGE_TOPOLOGY");
        if (d.graph.nodes.some((n) => !n.zh || !n.en || !n.sourcePath) || d.graph.edges.some((e) => !e.zh || !e.en || !e.type || !e.sourcePath)) errors.push("LABEL_OR_PROVENANCE");
      }
      if (id2 === "D05" && (d.graph.edges.filter((e) => e.type === "\u4E09\u5408").length !== 2 || d.graph.edges.filter((e) => e.type === "\u51B2").length !== 1 || d.graph.edges.some((e) => e.transformationEstablished))) errors.push("RELATION_SEMANTICS");
      if (id2 === "D14" && (d.graph.legend.length !== 7 || !d.graph.legend[0].zh.includes("\u4E0D\u5224\u5316\u571F"))) errors.push("TIMING_RELATIONS");
      if (spec.features.some((f) => !d.features.includes(f))) errors.push("FEATURE");
      if (!d.nodes.length) errors.push("NODES");
      if (!["D01", "D02", "D03"].includes(id2) && !d.graph.edges.length) errors.push("EDGES");
      if (id2 === "D14" && d.graph.layers.length !== 3) errors.push("LAYERS");
      if (id2 === "D03" && !d.nodes.every((n) => Number.isInteger(n.visible) && Number.isInteger(n.hidden))) errors.push("VISIBLE_HIDDEN");
      if (id2 === "D06" && !["wealth", "resource"].every((k) => d.graph.nodes.some((n) => n.id === k))) errors.push("CHAIN");
      if (["D07", "D13"].includes(id2) && (!d.graph.nodes.every((n) => d.graph.edges.filter((e) => e.from === n.id).length === 1) || d.graph.edges.length !== d.graph.nodes.length)) errors.push("CYCLE");
      if (id2 === "D13" && d.graph.nodes.length !== 5) errors.push("FIVE_FUNCTIONS");
      if (id2 === "D15" && (!d.graph.nodes.some((n) => n.id === "day") || d.graph.edges.length !== d.graph.nodes.length - 1)) errors.push("RADIAL");
      if (["D03", "D05", "D14"].includes(id2) && !d.graph.legend.length) errors.push("LEGEND");
      if (id2 === "D01" && !d.nodes.every((n) => Array.isArray(n.hiddenFacts) && n.stemGod)) errors.push("HIDDEN_FACTS");
      if (d.graph.edges.some((e) => !d.graph.nodes.some((n) => n.id === e.from) || !d.graph.nodes.some((n) => n.id === e.to))) errors.push("DANGLING_EDGE");
    }
    return { diagramId: id2, visualGrammarId: spec.grammar, requiredFeatures: spec.features, nodes: d?.graph.nodes.map((n) => n.id) || [], edges: d?.graph.edges || [], layers: d?.graph.layers || [], status: errors.length ? "FAIL" : "PASS", errors };
  });
}

