    reportItems.push({ id: r.reportId, title: `${r.method} \xB7 ${r.subjectName || "Report"}`, state: r.status, sourceClass: "PURCHASED_METHOD_REPORT", sourceVersion: r.version, href: `/api/account-method-reports?reportId=${encodeURIComponent(r.reportId)}` });
